    private QuizQuestion mkQ(Quiz quiz, int order, String text,
                             List<String> options, String correct) {
        String optionsJson = "[" +
                options.stream()
                        .map(o -> "\"" + o.replace("\"", "\\\"") + "\"")
                        .reduce((a, b) -> a + "," + b).orElse("") +
                "]";
        return QuizQuestion.builder()
                .quiz(quiz)
                .questionText(text)
                .answerOptions(optionsJson)
                .correctAnswer(correct)
                .orderIndex(order)
                .build();
    }
